import json
from pathlib import Path
L=[]
def v(w,r,m,meaning,pos,usage,jp,kana,roma,en,note):L.append(dict(word=w,reading=r,romaji=m,meaning=meaning,pos=pos,usage=usage,example=jp,example_reading=kana,example_romaji=roma,translation=en,nuance=note))
v('まるで','まるで','marude','just like; as if','adverb','まるで ... ようだ / みたいだ','この景色はまるで絵のようです。','このけしきはまるでえのようです。','Kono keshiki wa marude e no you desu.','This scenery is just like a painting.','Often introduces a vivid comparison; it does not claim the compared things are literally identical.')
v('むしろ','むしろ','mushiro','rather; if anything','adverb','Aより、むしろB','失敗ではなく、むしろよい経験でした。','しっぱいではなく、むしろよいけいけんでした。','Shippai dewa naku, mushiro yoi keiken deshita.','It was not a failure; rather, it was a good experience.','Corrects an evaluation toward a more appropriate alternative; not the same as a mild preference in every context.')
v('しかも','しかも','shikamo','moreover; what is more','conjunction','A。しかも、B。','この宿は安い。しかも、駅に近い。','このやどはやすい。しかも、えきにちかい。','Kono yado wa yasui. Shikamo, eki ni chikai.','This lodging is inexpensive. What is more, it is near the station.','Adds a notable fact strengthening the previous point. It can add disadvantages as well as benefits.')
v('せめて','せめて','semete','at least (a minimum wish)','adverb','せめて ... たい / てほしい','せめて一週間は休みたいです。','せめていっしゅうかんはやすみたいです。','Semete isshuukan wa yasumitai desu.','I would like at least a week off.','Expresses a minimum desired concession; 少なくとも is more neutral for a factual lower bound.')
v('なかなか','なかなか','nakanaka','not easily; quite','adverb','なかなか ... ない / なかなかいい','探している本がなかなか見つかりません。','さがしているほんがなかなかみつかりません。','Sagashite iru hon ga nakanaka mitsukarimasen.','I cannot seem to find the book I am looking for.','With a negative, progress is difficult or slow. With a positive evaluation, it can mean quite good.')
v('めったに','めったに','metta ni','rarely; seldom','adverb with negative','めったに ... ない','この町ではめったに雪が降りません。','このまちではめったにゆきがふりません。','Kono machi dewa metta ni yuki ga furimasen.','It rarely snows in this town.','Normally pairs with a negative predicate; めったに雪が降る is not the ordinary intended form.')
v('うっかり','うっかり','ukkari','carelessly; accidentally through inattention','adverb; suru use','うっかり忘れる','うっかり財布を家に忘れました。','うっかりさいふをいえにわすれました。','Ukkari saifu o ie ni wasuremashita.','I carelessly left my wallet at home.','The accident comes from inattention, unlike たまたま for neutral coincidence.')
v('思わず','おもわず','omowazu','without thinking; involuntarily','adverb','思わず笑う / 声を出す','友達の話を聞いて、思わず笑った。','ともだちのはなしをきいて、おもわずわらった。','Tomodachi no hanashi o kiite, omowazu waratta.','Hearing my friend’s story, I laughed without thinking.','Often describes a spontaneous reaction; not a deliberate action performed on purpose.')
v('とうとう','とうとう','toutou','finally; eventually','adverb','とうとう ... た','長く使っていた時計がとうとう壊れた。','ながくつかっていたとけいがとうとうこわれた。','Nagaku tsukatte ita tokei ga toutou kowareta.','The watch I had used for a long time finally broke.','Focuses on the eventual outcome after a process. The outcome may be desired or undesired.')
v('ついに','ついに','tsui ni','at last; finally','adverb','ついに完成する','三年かけて、ついに小説を書き終えました。','さんねんかけて、ついにしょうせつをかきおえました。','Sannen kakete, tsui ni shousetsu o kakioemashita.','After spending three years on it, I finally finished writing the novel.','Often foregrounds reaching a long-awaited endpoint, but is not restricted to positive results.')
v('ずいぶん','ずいぶん','zuibun','considerably; surprisingly much','adverb','ずいぶん ... た / ずいぶん高い','しばらく会わないうちに、ずいぶん背が伸びましたね。','しばらくあわないうちに、ずいぶんせがのびましたね。','Shibaraku awanai uchi ni, zuibun se ga nobimashita ne.','You have grown quite a lot since I last saw you.','Often includes the speaker’s surprise at the degree; much stronger than 少し.')
v('かなり','かなり','kanari','fairly; considerably','adverb','かなり時間がかかる','駅から歩くと、かなり時間がかかります。','えきからあるくと、かなりじかんがかかります。','Eki kara aruku to, kanari jikan ga kakarimasu.','It takes quite a while to walk from the station.','A substantial degree; often more neutral than the surprise conveyed by ずいぶん.')
v('わずか','わずか','wazuka','only a little; a mere','adverb; na-adjective','わずか三人 / わずかな時間','説明を聞く時間はわずか十分でした。','せつめいをきくじかんはわずかじゅっぷんでした。','Setsumei o kiku jikan wa wazuka juppun deshita.','There were only ten minutes to listen to the explanation.','Emphasizes smallness. Before a noun without a number, use な: わずかな時間.')
v('そろそろ','そろそろ','sorosoro','soon; about time','adverb','そろそろ出かける','もう九時です。そろそろ出かけましょう。','もうくじです。そろそろでかけましょう。','Mou kuji desu. Sorosoro dekakemashou.','It is already nine. It is about time we set off.','Suggests an appropriate time is approaching; also describes gradual or careful movement in other contexts.')
v('いよいよ','いよいよ','iyoiyo','at last; now finally','adverb','いよいよ明日 / いよいよ始まる','いよいよ明日、日本へ出発します。','いよいよあした、にほんへしゅっぱつします。','Iyoiyo ashita, Nihon e shuppatsu shimasu.','At last, I leave for Japan tomorrow.','Often adds anticipation of an important stage. It can also mean increasingly in some contexts.')
v('すでに','すでに','sude ni','already','adverb','すでに終わっている','受付はすでに終了しています。','うけつけはすでにしゅうりょうしています。','Uketsuke wa sude ni shuuryou shite imasu.','Registration has already closed.','More formal or written than もう; does not carry all the other meanings of もう, such as “another.”')
v('あらかじめ','あらかじめ','arakajime','in advance; beforehand','adverb','あらかじめ予約する / 確認する','参加する人数をあらかじめ教えてください。','さんかするにんずうをあらかじめおしえてください。','Sanka suru ninzuu o arakajime oshiete kudasai.','Please tell us the number of participants in advance.','Often used in planned arrangements and notices; 前もって is a close everyday equivalent.')
v('しばらく','しばらく','shibaraku','for a while; for some time','adverb','しばらく待つ / しばらく会っていない','雨がやむまで、ここでしばらく待ちます。','あめがやむまで、ここでしばらくまちます。','Ame ga yamu made, koko de shibaraku machimasu.','I will wait here for a while until the rain stops.','The length is context-dependent, not a fixed number of minutes; it can describe a long absence too.')
v('まもなく','まもなく','mamonaku','soon; shortly','adverb','まもなく到着する','まもなく三番線に電車が到着します。','まもなくさんばんせんにでんしゃがとうちゃくします。','Mamonaku sanbansen ni densha ga touchaku shimasu.','A train will shortly arrive on track three.','Common in announcements. そろそろ more often suggests that it is becoming time for an action.')
v('ますます','ますます','masumasu','more and more; increasingly','adverb','ますます ... なる','日本語を学んで、旅行がますます楽しくなりました。','にほんごをまなんで、りょこうがますますたのしくなりました。','Nihongo o manande, ryokou ga masumasu tanoshiku narimashita.','Learning Japanese has made travel even more enjoyable.','Intensifies an already existing tendency or state; it does not merely mean “then.”')
v('だんだん','だんだん','dandan','gradually','adverb','だんだん ... なる','新しい仕事にだんだん慣れてきました。','あたらしいしごとにだんだんなれてきました。','Atarashii shigoto ni dandan narete kimashita.','I have gradually become used to my new job.','Emphasizes step-by-step change. ますます emphasizes increasing degree from an existing state.')
v('たまたま','たまたま','tamatama','by chance; coincidentally','adverb','たまたま会う','駅でたまたま昔の先生に会いました。','えきでたまたまむかしのせんせいにあいました。','Eki de tamatama mukashi no sensei ni aimashita.','I happened to meet my former teacher at the station.','A neutral coincidence; it does not imply carelessness as うっかり does.')
v('わざと','わざと','wazato','on purpose; deliberately','adverb','わざと間違える','練習のために、先生はわざと間違えました。','れんしゅうのために、せんせいはわざとまちがえました。','Renshuu no tame ni, sensei wa wazato machigaemashita.','The teacher made a deliberate mistake for practice.','Can describe negative or harmless deliberate behavior. It contrasts with accidentally doing something.')
v('わざわざ','わざわざ','wazawaza','go out of one’s way; take the trouble','adverb','わざわざ来る / 届ける','わざわざ駅まで来てくれて、ありがとう。','わざわざえきまできてくれて、ありがとう。','Wazawaza eki made kite kurete, arigatou.','Thank you for taking the trouble to come to the station.','Highlights extra effort, often gratefully; can also criticize unnecessary effort. It is not the same as わざと.')
v('つい','つい','tsui','unintentionally; just (recently)','adverb','つい ... てしまう / ついさっき','お菓子を見ると、つい買ってしまいます。','おかしをみると、ついかってしまいます。','Okashi o miru to, tsui katte shimaimasu.','When I see sweets, I cannot help buying them.','Here it means doing something despite intentions. In ついさっき, it means just a moment ago.')
v('ふと','ふと','futo','suddenly; without deliberate thought','adverb','ふと思い出す / 気が付く','帰り道で、ふと友達の言葉を思い出した。','かえりみちで、ふとともだちのことばをおもいだした。','Kaerimichi de, futo tomodachi no kotoba o omoidashita.','On the way home, my friend’s words suddenly came to mind.','Often used for an unplanned thought, glance, or realization, rather than a dramatic external event.')
v('必ずしも','かならずしも','kanarazushimo','not necessarily (with negative)','adverb with negative','必ずしも ... ない','有名な店が必ずしも安いとは限りません。','ゆうめいなみせがかならずしもやすいとはかぎりません。','Yuumei na mise ga kanarazushimo yasui to wa kagirimasen.','Famous shops are not necessarily inexpensive.','Usually pairs with a negative or qualified negative; 必ず alone means invariably/without fail.')
v('決して','けっして','kesshite','never; by no means (with negative)','adverb with negative','決して ... ない','この約束は決して忘れません。','このやくそくはけっしてわすれません。','Kono yakusoku wa kesshite wasuremasen.','I will never forget this promise.','A strong negative assertion. It is stronger than not often, and differs from 必ずしもない, not necessarily.')
v('別に','べつに','betsu ni','not particularly; separately','adverb','別に ... ない / 別に用意する','別に怒っているわけではありません。','べつにおこっているわけではありません。','Betsu ni okotte iru wake dewa arimasen.','It is not that I am particularly angry.','With a negative, it downplays a feeling or issue; standalone 別に can sound curt. Another sense is separately.')
v('まさか','まさか','masaka','surely not; an unexpected possibility','adverb; exclamation','まさか ... とは思わなかった','まさかここで会うとは思いませんでした。','まさかここであうとはおもいませんでした。','Masaka koko de au to wa omoimasen deshita.','I never expected to meet you here.','Conveys strong surprise or disbelief; does not by itself prove something is impossible.')
ex=[dict(type='choice',question='Choose the word for doing something on purpose: 先生は練習のために（　）間違えた。',options=['わざと','うっかり','たまたま','ふと'],answer='わざと',explanation='The teacher intentionally creates an error for practice.'),dict(type='error correction',question='Correct the intended “It rarely snows”: めったに雪が降ります。',answer='めったに雪が降りません。',explanation='めったに normally pairs with a negative predicate.'),dict(type='translation',question='Translate: わざわざ来てくれてありがとう。',answer='Thank you for taking the trouble to come.',explanation='わざわざ credits the extra effort; it is not a complaint about deliberate behavior.'),dict(type='meaning contrast',question='Explain 必ずしも安いとは限らない versus 決して安くない.',answer='The first means not necessarily cheap; the second means by no means cheap.',explanation='Partial denial allows cheap cases; the strong negative denies cheapness.'),dict(type='reading',question='Give the reading of 思わず and 必ずしも.',answer='おもわず; かならずしも.',explanation='Learn these fixed adverbial forms as whole words.'),dict(type='sentence production',question='Write a sentence saying that you gradually became used to the job, using だんだん.',answer='仕事にだんだん慣れてきました。',explanation='だんだん describes gradual change, and 慣れる takes the situation with に.')]
out=dict(id=31,title='Adverbs that change the message',overview='Learn degree, intention, timing, and negative polarity. The surrounding predicate is essential to the meaning.',items=L,exercises=ex)
Path(__file__).with_name('vocab_31.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
